      <!-- Mobile Sidebar (Slides from left on mobile) -->
      <DesktopSidebar
        v-if="isMobile"
        :user-name="$user?.username || 'User'"
        :user-subtitle="'Pro'"
        :is-mobile="true"
        :is-mobile-expanded="showMobileSidebarOverlay"
        class="z-150"
        @close="showMobileSidebarOverlay = false"
        @settings="openAccountSettings"
      />

      <!-- Main Content with Router (Flex context for scrollable children) -->
      <div class="grow flex flex-col min-h-0">
        <RouterView />
      </div>

      <!-- Mobile Bottom Bar (Portrait on mobile) -->
      <MobileBottomBar
        v-if="isMobilePortrait && showMobileBottomBar"
        :user-name="$user?.username || 'User'"
        @show-menu="showMobileSidebarOverlay = true"
      />

      <!-- Toast Notifications -->
      <Toast ref="toastComponent" />
    </div>
  </div>

  <div class="flex flex-col items-center justify-center w-full h-full font-2xl px-4 py-2" v-else>
    <div class="animate-pulse font-mono text-green-600">Wake up, codx-junior...</div>
  </div>
</template>

<script>
export default {
  data() {
    return {
      pendingProjectSwitch: null,
      windowWidth: 0,
      windowHeight: 0,
      showMobileSidebarOverlay: false
    }
  },
  computed: {
    isLogin() {
      return !this.$user
    },
    isDesktop() {
      return this.windowWidth >= 768
    },
    isMobile() {
      return this.windowWidth < 768
    },
    isLandscape() {
      return this.windowWidth > this.windowHeight
    },
    isPortrait() {
      return this.windowHeight > this.windowWidth
    },
    isDesktopLandscape() {
      return this.isDesktop && this.isLandscape
    },
    isMobileLandscape() {
      return this.isMobile && this.isLandscape
    },
    isMobilePortrait() {
      return this.isMobile && this.isPortrait
    },
    layoutClasses() {
      if (this.isMobilePortrait) {
        return 'flex-col'
      }
      return 'flex-row'
    },
    infoNotifications() {
      return this.$ui.notifications.filter(n => n.type !== 'error')
    },
    errorNotifications() {
      return this.$ui.notifications.filter(n => n.type === 'error')
    },
    showMobileBottomBar() {
      const { name, params } = this.$route
      return name != 'chat' || !params?.chatId
    }
  },
  watch: {
    '$ui.projectLoadingState': {
      handler(newState) {
        if (!newState || !newState.isLoading) return
        const overlay = this.$refs.loadingOverlay
        if (overlay && typeof overlay.startLoading === 'function') {
          overlay.startLoading(newState.projectName)
        }
      },
      deep: true
    },
    '$route'() {
      this.showMobileSidebarOverlay = false
    }
  },
  mounted() {
    this.updateDimensions()
    window.addEventListener('resize', this.updateDimensions)
  },
  beforeUnmount() {
    window.removeEventListener('resize', this.updateDimensions)
  },
  methods: {
    updateDimensions() {
      this.windowWidth = window.innerWidth
      this.windowHeight = window.innerHeight
    },
    retryProjectLoad() {
      if (this.pendingProjectSwitch) {
        this.$storex.projects.activeProjectChanged(this.pendingProjectSwitch)
      }
    },
    cancelProjectLoad() {
      this.pendingProjectSwitch = null
      this.$storex.ui.setProjectLoadingState({ isLoading: false })
    },
    openAccountSettings() {
      this.$emit('settings')
    }
  }
}
</script>
```

## Changes Summary

| Element | Change | Reason |
|---------|--------|--------|
| **Main Content Wrapper** | Changed from `<div class="grow">` to `<div class="grow flex flex-col min-h-0">` | Creates proper flex context so children can use `overflow-y-auto` and `flex-1`. `min-h-0` prevents flex items from exceeding parent bounds |
| **RouterView Container** | Now wrapped in flex column with height constraints | Allows nested components (like KanbanList) to properly calculate scrollable heights |

## Why This Fixes It

1. **Flex Column Context:** The main content wrapper is now `flex flex-col` which establishes a flex formatting context
2. **Min Height: 0:** `min-h-0` allows flex items to shrink below content size, preventing overflow
3. **Proper Height Calculation:** When KanbanList uses `overflow-y-auto flex-1`, it now has a bounded parent to measure against
4. **Mobile Bottom Bar Compatible:** The main content respects the bottom bar height automatically since the layout is `flex-col`

## Result

✅ KanbanList scrolling now works on mobile portrait  
✅ Height is properly constrained by App.vue layout  
✅ Bottom bar doesn't interfere with scroll area  
✅ Desktop/tablet views unchanged

